package main

const jsResearchHistory = `
function researchHistoryProblem(e){return e.name==='TypeError'&&e.message==='Failed to fetch'?'無法連接服務，請檢查網路後再試。':e.message;}
function validResearchRunRecord(r,owner=''){return r&&typeof r.id==='string'&&r.id.length>0&&typeof r.status==='string'&&Number.isSafeInteger(r.started_at)&&(!owner||r.schedule_id===owner)&&['budget','used','probe_budget','probes_used'].every(k=>r[k]===null||Number.isSafeInteger(r[k])&&r[k]>=0);}
function researchRunUsage(r){return r.budget===null||r.used===null?'HTTP 用量未提供':r.used+' / '+r.budget+' 次 HTTP';}
function researchRunName(r){return (r.schedule_name?r.schedule_name+' · ':'研究 · ')+(researchRunStates[r.status]||r.status);}
function researchHistory(state=null){
 state=state||{owner:'',cursors:[''],index:0,page:null};
 const restore=fresh=>{if(fresh&&state.page)state={...state,page:{...state.page,runs:state.page.runs.map(r=>r.id===fresh.id?fresh:r)}};return researchHistory(state);};
 const box=modal('研究歷程'),ticket=detailVersion,current=()=>detailCurrent(ticket),filters=el('form'),owner=el('select'),label=el('label','研究歷程排程'),problem=el('p'),meter=el('p'),list=el('div',undefined,'cards'),controls=el('div',undefined,'actions');
 owner.setAttribute('aria-label','研究歷程排程');option(owner,'','全部研究');for(const s of researchScheduleState?.schedules||[])option(owner,s.id,s.name);if(state.owner&&![...owner.options].some(o=>o.value===state.owner))option(owner,state.owner,'指定排程 · '+state.owner);owner.value=state.owner;label.append(owner);filters.className='toolbar';filters.append(label,el('button','套用研究範圍'));box.append(el('p','研究紀錄持續保留。','section-description'),filters);
 const lookup=el('form'),runID=field(lookup,'研究紀錄 ID'),lookupPanel=el('details');runID.required=true;runID.maxLength=128;lookup.append(el('button','開啟指定紀錄'));lookupPanel.append(el('summary','依紀錄 ID 開啟'),lookup);box.append(lookupPanel);
 problem.id='research-history-problem';problem.setAttribute('role','status');meter.id='research-history-meter';list.id='research-history-list';box.append(problem,meter,controls,list);
 const previous=el('button','上一頁','ghost'),next=el('button','下一頁','ghost'),refresh=el('button','更新歷程清單','ghost');for(const b of [previous,next,refresh])b.type='button';controls.append(previous,next,refresh);let loading=false;
 const setBusy=()=>{previous.disabled=loading||!state.page||state.index===0;next.disabled=loading||!state.page?.next_cursor;refresh.disabled=loading;filters.querySelectorAll('button,select').forEach(n=>n.disabled=loading);lookup.querySelectorAll('button,input').forEach(n=>n.disabled=loading);list.setAttribute('aria-busy',String(loading));};
 const render=()=>{const page=state.page;if(!page)return;owner.value=state.owner;list.replaceChildren();const name=state.owner?([...owner.options].find(o=>o.value===state.owner)?.textContent||'指定排程'):'全部研究';meter.textContent=name+' · '+page.total+' 輪'+(page.runs.length?' · 第 '+(state.index*50+1)+'–'+(state.index*50+page.runs.length)+' 輪':'');for(const r of page.runs){const card=item(list,researchRunName(r),new Date(r.started_at).toLocaleString()+' · '+researchRunUsage(r),()=>researchRunDetail(r,null,restore));card.dataset.researchRun=r.id;}if(!page.runs.length)list.append(el('p','這個範圍尚無研究紀錄。'));setBusy();};
 const load=async request=>{if(loading||!current())return;loading=true;problem.textContent='正在讀取研究歷程…';setBusy();try{const q=new URLSearchParams({limit:'50'});if(request.owner)q.set('schedule_id',request.owner);if(request.cursors[request.index])q.set('cursor',request.cursors[request.index]);const page=await api('/research/history?'+q);if(!current())return;if(!Array.isArray(page.runs)||page.runs.length>50||!Number.isSafeInteger(page.total)||page.total<page.runs.length||typeof page.next_cursor!=='string'||page.next_cursor.length>2048||new Set(page.runs.map(r=>r.id)).size!==page.runs.length||page.runs.some(r=>!validResearchRunRecord(r,request.owner)))throw Error('研究歷程的紀錄或排程範圍不符。');state={...request,page};problem.textContent='';render();}catch(e){if(current())problem.textContent=(state.page?'讀取失敗，仍顯示上次成功的歷程。 ':'無法讀取研究歷程。 ')+researchHistoryProblem(e);}finally{loading=false;if(current())setBusy();}};
 filters.addEventListener('submit',e=>{e.preventDefault();load({owner:owner.value,cursors:[''],index:0,page:state.page});});lookup.addEventListener('submit',e=>{e.preventDefault();if(!loading)researchRunDetail({id:runID.value.trim(),schedule_id:owner.value},null,restore);});previous.addEventListener('click',()=>load({...state,index:state.index-1}));next.addEventListener('click',()=>load({...state,cursors:[...state.cursors.slice(0,state.index+1),state.page.next_cursor],index:state.index+1}));refresh.addEventListener('click',()=>load({owner:state.owner,cursors:[''],index:0,page:state.page}));if(state.page){render();setBusy();}else load(state);
}
async function researchRunDetail(initialRun,unusedTaskSnapshot=null,returnTo=null){
 const box=modal('研究紀錄'),ticket=detailVersion,current=()=>detailCurrent(ticket),actions=el('div',undefined,'actions'),problem=el('p'),body=el('div');box.append(actions,problem,body);problem.id='research-run-problem';problem.setAttribute('role','status');body.id='research-run-snapshot';
 let reading=false,writing=false,trusted=false,pendingWrite=false,snapshot=null,draft={http:'0',probes:'0',retry:false};
 const setBusy=()=>{refresh.disabled=reading||writing;if(back)back.disabled=writing;body.setAttribute('aria-busy',String(reading));body.querySelectorAll('[data-research-write]').forEach(n=>n.disabled=reading||writing||!trusted||n.dataset.researchLocked==='true');};
 const capture=()=>{const f=body.querySelector('#research-resume-form');if(f)draft={http:f.elements.additional_budget.value,probes:f.elements.additional_probes.value,retry:f.elements.retry_failed.checked};};
 const mark=(n,locked=false)=>{n.dataset.researchWrite='true';n.dataset.researchLocked=String(locked);return n;};
 const mutate=async(action,value={})=>{if(writing||reading||!trusted||!current())return;capture();writing=true;trusted=false;pendingWrite=true;problem.textContent='正在保存研究操作…';setBusy();try{await submit('/research/control',{id:initialRun.id,action,...value});if(!current())return;problem.textContent='操作已保存，正在讀取最新紀錄…';const restored=await read(true);if(current()&&restored){if(returnTo)returnTo(snapshot.run);else $('detail').close();}await loadResearch();}catch(e){if(current())problem.textContent='操作結果待確認。請先更新執行紀錄，讀取保存狀態後再決定下一步。 '+researchHistoryProblem(e);}finally{writing=false;if(current())setBusy();}};
 const mutationButton=(parent,label,action)=>{const b=mark(el('button',label,'ghost'));b.type='button';b.addEventListener('click',()=>mutate(action));parent.append(b);};
 const render=(r,tasks)=>{
  body.replaceChildren();body.dataset.runId=r.id;const header=detailSection(body,researchRunName(r),new Date(r.started_at).toLocaleString()),usage=el('p',researchRunUsage(r));usage.id='research-run-meter';header.append(usage);detailRows(header,[['紀錄 ID',r.id]]);if(r.checkpoint)header.append(el('p',r.checkpoint));renderResearchRunResources(body,r.summary?.research_resources);researchProbeHistory(body,'run_id='+encodeURIComponent(r.id),ticket);factsView(body,'本輪結果',r.summary||{});
  for(const t of tasks){const d=el('details');d.append(el('summary',t.kind+' · '+t.status+' · '+t.attempts+' 次嘗試'));factsView(d,'計畫',t.payload);renderResearchOriginWait(d,t,r);renderResearchRetry(d,t,r);renderAAResearchProgress(d,t,r);renderBraveResearchProgress(d,t,r);renderResearchInferenceLimit(d,t,r);renderResearchResourceLimit(d,t,r);factsView(d,'結果',t.result);body.append(d);}
  if(['QUEUED','RUNNING'].includes(r.status))mutationButton(body,'暫停研究','PAUSE');
  const resumable=!r.query_comparison&&!initialRun.query_comparison&&Number.isInteger(r.budget)&&r.budget>=0&&r.budget<=200&&Number.isInteger(r.probe_budget)&&r.probe_budget>=0&&r.probe_budget<=10&&['PAUSED','BUDGET_EXHAUSTED','COMPLETED'].includes(r.status)&&tasks.some(t=>['QUEUED','INTERRUPTED','BUDGET_EXHAUSTED'].includes(t.status)||(t.status==='FAILED'&&t.attempts<3&&!t.result?.aa_progress?.stopped_reason&&!t.result?.brave_progress?.stopped_reason));
  if(resumable){const f=el('form');f.id='research-resume-form';const extra=mark(field(f,'追加 HTTP 預算','number',draft.http)),probe=mark(field(f,'追加推論預算','number',draft.probes),!!r.schedule_id),retry=mark(el('input')),label=el('label','重試失敗項目','check');extra.name='additional_budget';probe.name='additional_probes';extra.required=probe.required=true;extra.min=0;extra.max=200-r.budget;probe.min=0;probe.max=r.schedule_id?0:10-r.probe_budget;retry.name='retry_failed';retry.type='checkbox';retry.checked=draft.retry;label.prepend(retry);f.append(label,mark(el('button','確認恢復研究')));if(r.schedule_id)f.append(el('p','此輪屬於排程；須遵守原排程、每輪與每日已核准上限。'));body.append(f);f.addEventListener('submit',e=>{e.preventDefault();if(f.reportValidity())mutate('RESUME',{additional_budget:Number(extra.value),additional_probes:Number(probe.value),retry_failed:retry.checked});});}
  if(['PAUSED','QUEUED','RUNNING','BUDGET_EXHAUSTED'].includes(r.status))mutationButton(body,'取消研究','CANCEL');
 };
 const read=async(afterWrite=false)=>{if(reading||writing&&!afterWrite||!current())return false;capture();reading=true;trusted=false;problem.textContent='正在讀取這一輪研究…';setBusy();try{let q='/research/runs?id='+encodeURIComponent(initialRun.id);if(initialRun.schedule_id)q+='&schedule_id='+encodeURIComponent(initialRun.schedule_id);const runs=await api(q);if(!current())return false;if(!Array.isArray(runs)||runs.length!==1||runs[0].id!==initialRun.id||!validResearchRunRecord(runs[0],initialRun.schedule_id))throw Error('找不到指定範圍的研究紀錄。');const r=runs[0],tasks=await api('/research/tasks?run_id='+encodeURIComponent(r.id));if(!current())return false;if(!Array.isArray(tasks)||new Set(tasks.map(t=>t.id)).size!==tasks.length||tasks.some(t=>typeof t.id!=='string'||!t.id||t.run_id!==r.id||typeof t.kind!=='string'||typeof t.status!=='string'||!Number.isSafeInteger(t.attempts)||t.attempts<0))throw Error('研究任務的紀錄範圍不符。');const wasPending=pendingWrite;if(wasPending)draft={http:'0',probes:'0',retry:false};render(r,tasks);snapshot={run:r,tasks};pendingWrite=false;trusted=true;problem.textContent=wasPending?'已讀取保存狀態；先前操作不會自動重送。':'';return true;}catch(e){if(current())problem.textContent=(snapshot?'讀取失敗，上次成功的紀錄與未送出的修改保留。 ':'無法讀取這一輪研究。 ')+researchHistoryProblem(e);return false;}finally{reading=false;if(current())setBusy();}};
 const refresh=action(actions,'更新執行紀錄',()=>read()),back=returnTo?action(actions,'返回研究歷程',()=>returnTo(snapshot?.run)):null;await read();
}
`
